// Bộ phân giải ký tự & phát âm Hán-Việt tự động 100% chuẩn xác dựa trên STANDARD_CHAR_DB
window.annotateChineseText = function(zhText) {
  if (!zhText) return { chars_annotated: [], pinyin: '', hanviet: '' };
  const db = window.STANDARD_CHAR_DB || {};
  const puncts = new Set(['，', '。', '！', '？', '；', '：', '、', '"', "'", '(', ')', '（', '）', '《', '》', ' ']);
  const chars_annotated = [];
  const pyTokens = [];
  const hvTokens = [];

  for (let i = 0; i < zhText.length; i++) {
    const ch = zhText[i];
    if (puncts.has(ch)) {
      chars_annotated.push({ ch, py: '', hv: '', is_punct: true });
      if (ch !== ' ') {
        pyTokens.push(ch);
        hvTokens.push(ch);
      }
    } else {
      const entry = db[ch] || { py: '', hv: '' };
      chars_annotated.push({
        ch,
        py: entry.py,
        hv: entry.hv,
        is_punct: false
      });
      if (entry.py) pyTokens.push(entry.py);
      if (entry.hv) hvTokens.push(entry.hv);
    }
  }

  return {
    chars_annotated,
    pinyin: pyTokens.join(' '),
    hanviet: hvTokens.join(' ')
  };
};

// Trích xuất các bài đọc/hội thoại từ Giáo trình Chuẩn HSK 1-9 (Lấy Pinyin chuẩn nguyên bản)
window.extractCurriculumPassages = function(levelStr) {
  if (!window.HSK_FULL_CURRICULUM) return [];
  const lvlNum = (levelStr || '').replace(/[^0-9]/g, '');
  const lvlKey = lvlNum ? ('HSK ' + lvlNum) : 'HSK 4';
  const lessons = window.HSK_FULL_CURRICULUM[lvlKey] || [];
  const results = [];

  lessons.forEach(l => {
    (l.texts || []).forEach((t, tIdx) => {
      const textTitle = t.title || `Bài khóa ${tIdx + 1}`;
      let fullZh = '';
      let fullPy = '';
      let fullEn = '';
      if (t.lines && t.lines.length) {
        fullZh = t.lines.map(line => line.zh).join(' ');
        fullPy = t.lines.map(line => line.py).join(' ');
        fullEn = t.lines.map(line => `${line.speaker}: ${line.en}`).join(' | ');
      } else if (t.dialogue && t.dialogue.length) {
        fullZh = t.dialogue.map(d => d.zh).join(' ');
        fullPy = t.dialogue.map(d => d.pinyin || d.py || '').join(' ');
        fullEn = t.dialogue.map(d => `${d.speaker}: ${d.en || d.vi || ''}`).join(' | ');
      }
      if (fullZh && fullZh.length >= 10) {
        results.push({
          id: `curr-${l.no}-${tIdx}`,
          title: `[Giáo trình ${lvlKey}] Bài ${l.no}: ${textTitle}`,
          sample_zh: fullZh,
          sample_pinyin: fullPy, // GIỮ NGUYÊN PINYIN NGUYÊN BẢN CHUẨN XÁC TỪ GIÁO TRÌNH
          sample_vi: fullEn || t.sceneEn || 'Trích đoạn bài khóa giáo trình chuẩn.',
          is_curriculum: true
        });
      }
    });
  });

  return results;
};

// Bộ sinh đoạn văn mẫu chuẩn ngữ pháp theo từ vựng người dùng tự chọn
window.generateCustomEssay = function(level, wordsInput, topicHint) {
  const words = Array.isArray(wordsInput) 
    ? wordsInput 
    : (wordsInput || '').split(/[,，\s]+/).map(w => w.trim()).filter(Boolean);

  const lvl = parseInt(level) || 3;
  let title = `[Tự tạo] Luyện viết đoạn ${words.length} từ: ${words.join(', ')}`;
  let zhText = '';
  let viText = '';

  if (words.length === 0) {
    zhText = '学习汉语是一件非常快乐的事情。每天进步一点点，我们就能取得好成绩。';
    viText = 'Học tiếng Trung là một việc vô cùng vui vẻ. Mỗi ngày tiến bộ một chút, chúng ta nhất định sẽ đạt được thành tích tốt.';
  } else if (words.length === 1) {
    const w1 = words[0];
    zhText = `在日常生活中，【${w1}】对我们来说非常重要。我们应该认真对待，努力把事情做得更好。`;
    viText = `Trong cuộc sống hàng ngày, 【${w1}】 đối với chúng ta vô cùng quan trọng. Chúng ta nên nghiêm túc đối diện và nỗ lực làm mọi việc tốt hơn.`;
  } else if (words.length === 2) {
    const [w1, w2] = words;
    zhText = `只要我们能坚持【${w1}】，就一定能在未来的生活中收获【${w2}】。这是成功的关键秘诀。`;
    viText = `Chỉ cần chúng ta có thể kiên trì 【${w1}】, nhất định sẽ gặt hái được 【${w2}】 trong cuộc sống tương lai. Đây chính là bí quyết then chốt của thành công.`;
  } else if (words.length === 3) {
    const [w1, w2, w3] = words;
    if (lvl <= 2) {
      zhText = `我非常喜欢【${w1}】。每天我和朋友一起【${w2}】，大家都觉得【${w3}】，心里特别高兴。`;
      viText = `Tôi rất thích 【${w1}】. Mỗi ngày tôi cùng bạn bè 【${w2}】, mọi người đều cảm thấy 【${w3}】, trong lòng vô cùng vui vẻ.`;
    } else if (lvl <= 4) {
      zhText = `为了能够更好地【${w1}】，我们平时不仅要注重【${w2}】，而且应该养成【${w3}】的优良习惯。`;
      viText = `Để có thể 【${w1}】 tốt hơn, bình thường chúng ta không những phải chú trọng 【${w2}】, mà còn nên hình thành thói quen tốt 【${w3}】.`;
    } else {
      zhText = `在追求【${w1}】的漫长道路上，唯有深刻理解【${w2}】的核心内涵，才能真正实现【${w3}】的重大跨越。`;
      viText = `Trên con đường dài theo đuổi 【${w1}】, chỉ khi hiểu sâu sắc nội hàm cốt lõi của 【${w2}】, chúng ta mới có thể thực sự hiện thực hóa bước nhảy vọt quan trọng của 【${w3}】.`;
    }
  } else {
    const [w1, w2, w3, w4] = words;
    zhText = `想要做好【${w1}】，必须保持【${w2}】的心态。在面对各种挑战时，善于运用【${w3}】，最终定能迎来【${w4}】的美好成果。`;
    viText = `Muốn làm tốt 【${w1}】, cần phải duy trì tâm thái 【${w2}】. Khi đối diện các thử thách, khéo léo vận dụng 【${w3}】, cuối cùng nhất định sẽ đón nhận thành quả tốt đẹp của 【${w4}】.`;
  }

  const annotation = window.annotateChineseText(zhText);

  return {
    id: 'custom-' + Date.now(),
    level: lvl,
    title,
    words: words.map(w => ({ zh: w })),
    sample_zh: zhText,
    sample_pinyin: annotation.pinyin,
    sample_hanviet: annotation.hanviet,
    sample_vi: viText,
    chars_annotated: annotation.chars_annotated,
    is_custom: true
  };
};
